/*
    Parallel reduction kernels
*/

#ifndef _REDUCE_KERNEL_H_
#define _REDUCE_KERNEL_H_

#include <cooperative_groups.h>
#include <cooperative_groups/reduce.h>
#include <stdio.h>

namespace cg = cooperative_groups;

// Utility class used to avoid linker errors with extern
// unsized shared memory arrays with templated type
template <class T> struct SharedMemory
{
    __device__ inline operator T *()
    {
        extern __shared__ int __smem[];
        return (T *)__smem;
    }

    __device__ inline operator const T *() const
    {
        extern __shared__ int __smem[];
        return (T *)__smem;
    }
};

// specialize for double to avoid unaligned memory
// access compile errors
template <> struct SharedMemory<double>
{
    __device__ inline operator double *()
    {
        extern __shared__ double __smem_d[];
        return (double *)__smem_d;
    }

    __device__ inline operator const double *() const
    {
        extern __shared__ double __smem_d[];
        return (double *)__smem_d;
    }
};

template <class T> __device__ __forceinline__ T warpReduceSum(unsigned int mask, T mySum)
{
    for (int offset = warpSize / 2; offset > 0; offset /= 2) {
        mySum += __shfl_down_sync(mask, mySum, offset);
    }
    return mySum;
}

#if __CUDA_ARCH__ >= 800
// Specialize warpReduceFunc for int inputs to use __reduce_add_sync intrinsic
// when on SM 8.0 or higher
template <> __device__ __forceinline__ int warpReduceSum<int>(unsigned int mask, int mySum)
{
    mySum = __reduce_add_sync(mask, mySum);
    return mySum;
}
#endif

/*
    Parallel sum reduction using shared memory
    - takes log(n) steps for n input elements
    - uses n threads
    - only works for power-of-2 arrays
*/

/* This reduction interleaves which threads are active by using the modulo
   operator.  This operator is very expensive on GPUs, and the interleaved
   inactivity means that no whole warps are active, which is also very
   inefficient */
template <class T> __global__ void reduce0(T *g_idata, T *g_odata, unsigned int n)
{
    // Handle to thread block group
    cg::thread_block cta   = cg::this_thread_block();
    T               *sdata = SharedMemory<T>();

    // load shared mem
    unsigned int tid = threadIdx.x;
    unsigned int i   = blockIdx.x * blockDim.x + threadIdx.x;

    sdata[tid] = (i < n) ? g_idata[i] : 0;

    cg::sync(cta);

    // do reduction in shared mem
    for (unsigned int s = 1; s < blockDim.x; s *= 2) {
        // modulo arithmetic is slow!
        if ((tid % (2 * s)) == 0) {
            sdata[tid] += sdata[tid + s];
        }

        cg::sync(cta);
    }

    // write result for this block to global mem
    if (tid == 0)
        g_odata[blockIdx.x] = sdata[0];
}


#endif
extern "C" void run(const void*x,const void*k,const void*gy,void*out,void*scratch,int n,int h,int l,int ks)
{int count=n;int*input=(int*)x;int*temp=(int*)scratch;bool flip=false;
while(count>1){int blocks=(count+128-1)/128;
int*dest=flip?(int*)scratch+n+32768:(int*)scratch;
reduce0<int><<<blocks,128,128*sizeof(int)>>>(input,dest,count);
input=dest;count=blocks;flip=!flip;}
cudaMemcpyAsync(out,input,sizeof(int),cudaMemcpyDeviceToDevice);}

#include <cuda_runtime.h>

namespace {
constexpr int kThreads = 128;
constexpr int kInputTileElements = 2048;
constexpr int kPartialTileElements = 128;
constexpr int kFinalizerLimit = 128;
constexpr int kDirectLimit = 128;

__global__ void reduce_direct(const int *input, int n, int *out)
{
    __shared__ long long sums[kThreads];
    const unsigned int tid = threadIdx.x;
    long long value = 0;

    for (int i = static_cast<int>(tid); i < n; i += blockDim.x) {
        value += static_cast<long long>(input[i]);
    }
    sums[tid] = value;
    __syncthreads();

    for (unsigned int stride = 1; stride < blockDim.x; stride *= 2) {
        if ((tid % (2 * stride)) == 0) {
            sums[tid] += sums[tid + stride];
        }
        __syncthreads();
    }

    if (tid == 0) {
        *out = static_cast<int>(sums[0]);
    }
}

__global__ void write_zero(int *out)
{
    if (threadIdx.x == 0) {
        *out = 0;
    }
}

// Each CTA covers a bounded tile. All stages retain the same 128-thread
// shared-memory reduction tree and accumulate exact int64 partial sums.
template <typename Input, int TileElements>
__global__ void reduce_tiles(const Input *input, long long *partials, int n)
{
    __shared__ long long sums[kThreads];
    const unsigned int tid = threadIdx.x;
    const long long begin = static_cast<long long>(blockIdx.x) * TileElements + tid;
    const long long end = (static_cast<long long>(blockIdx.x) + 1LL) * TileElements;
    long long value = 0;

    for (long long i = begin; i < end && i < n; i += blockDim.x) {
        value += static_cast<long long>(input[i]);
    }
    sums[tid] = value;
    __syncthreads();

    for (unsigned int stride = 1; stride < blockDim.x; stride *= 2) {
        if ((tid % (2 * stride)) == 0) {
            sums[tid] += sums[tid + stride];
        }
        __syncthreads();
    }

    if (tid == 0) {
        partials[blockIdx.x] = sums[0];
    }
}

__global__ void finalize_partials(const long long *partials, int count, int *out)
{
    __shared__ long long sums[kThreads];
    const unsigned int tid = threadIdx.x;
    long long value = 0;

    for (int i = static_cast<int>(tid); i < count; i += blockDim.x) {
        value += partials[i];
    }
    sums[tid] = value;
    __syncthreads();

    for (unsigned int stride = 1; stride < blockDim.x; stride *= 2) {
        if ((tid % (2 * stride)) == 0) {
            sums[tid] += sums[tid + stride];
        }
        __syncthreads();
    }

    if (tid == 0) {
        *out = static_cast<int>(sums[0]);
    }
}
} // namespace

extern "C" void run(const void *x, const void *k, const void *gy,
                     void *out, void *scratch, int n, int h, int l, int ks)
{
    (void)k;
    (void)gy;
    (void)h;
    (void)l;
    (void)ks;

    if (out == nullptr || n < 0) {
        return;
    }
    if (n == 0) {
        write_zero<<<1, 1>>>(static_cast<int *>(out));
        return;
    }
    if (x == nullptr) {
        return;
    }
    if (n <= kDirectLimit) {
        reduce_direct<<<1, kThreads>>>(static_cast<const int *>(x), n,
                                       static_cast<int *>(out));
        return;
    }
    if (scratch == nullptr) {
        return;
    }

    const int initial_count = 1 + (n - 1) / kInputTileElements;
    long long *buffer0 = static_cast<long long *>(scratch);
    long long *buffer1 = buffer0 + initial_count;

    reduce_tiles<int, kInputTileElements><<<initial_count, kThreads>>>(
        static_cast<const int *>(x), buffer0, n);

    const long long *current = buffer0;
    int count = initial_count;
    bool write_buffer1 = true;

    while (count > kFinalizerLimit) {
        const int next_count = 1 + (count - 1) / kPartialTileElements;
        long long *next = write_buffer1 ? buffer1 : buffer0;
        reduce_tiles<long long, kPartialTileElements><<<next_count, kThreads>>>(
            current, next, count);
        current = next;
        count = next_count;
        write_buffer1 = !write_buffer1;
    }

    finalize_partials<<<1, kThreads>>>(current, count, static_cast<int *>(out));
}

